import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react()],
  server: {
    port: 5123,
    strictPort: true,
    host: true,
  },
})

/**
 * Mock API for the feed.
 *
 * In a real application this would be an HTTP request. For this demo we
 * simulate latency and use a cursor-based pagination scheme so the feed
 * can be exercised with `useInfiniteQuery`.
 */

export interface FeedItem {
  id: number
  title: string
  body: string
  author: string
}

export interface FeedPage {
  items: FeedItem[]
  nextCursor: number | null
}

const PAGE_SIZE = 5
const TOTAL_ITEMS = 25

const AUTHORS = [
  'Ada Lovelace',
  'Grace Hopper',
  'Alan Turing',
  'Margaret Hamilton',
  'Linus Torvalds',
]

const buildItem = (id: number): FeedItem => ({
  id,
  title: `Post #${id}: Thoughts on server state`,
  body: `This is post number ${id}. It illustrates a single page entry returned by the mock feed API.`,
  author: AUTHORS[id % AUTHORS.length],
})

const generateAllItems = (): FeedItem[] =>
  Array.from({ length: TOTAL_ITEMS }, (_, index) => buildItem(index + 1))

const ALL_ITEMS = generateAllItems()

/**
 * Fetch a single page of feed items.
 *
 * @param cursor - The id of the last item from the previous page, or `null`
 *                 when requesting the first page.
 */
export const fetchFeedPage = async (
  cursor: number | null,
): Promise<FeedPage> => {
  // Simulate network latency so the loading state is visible.
  await new Promise((resolve) => setTimeout(resolve, 400))

  const startIndex = cursor === null ? 0 : cursor
  const endIndex = startIndex + PAGE_SIZE
  const items = ALL_ITEMS.slice(startIndex, endIndex)
  const nextCursor = endIndex < ALL_ITEMS.length ? endIndex : null

  return { items, nextCursor }
}

import { useInfiniteQuery } from '@tanstack/react-query'
import { fetchFeedPage, type FeedItem } from './api'
import './Feed.css'

type FeedPage = Awaited<ReturnType<typeof fetchFeedPage>>

export const Feed = () => {
  const {
    data,
    error,
    fetchNextPage,
    hasNextPage,
    isFetching,
    isFetchingNextPage,
    status,
  } = useInfiniteQuery<FeedPage, Error>({
    queryKey: ['feed'],
    queryFn: ({ pageParam }) => fetchFeedPage(pageParam as number | null),
    initialPageParam: null as number | null,
    getNextPageParam: (lastPage) => lastPage.nextCursor,
  })

  if (status === 'pending') {
    return <div className="feed-status">Loading feed…</div>
  }

  if (status === 'error') {
    return (
      <div className="feed-status feed-status--error">
        Error loading feed: {error.message}
      </div>
    )
  }

  const items: FeedItem[] = data?.pages.flatMap((page) => page.items) ?? []

  return (
    <div className="feed">
      <header className="feed__header">
        <h1>Infinite Feed</h1>
        <p>
          {items.length} item{items.length === 1 ? '' : 's'} loaded
          {hasNextPage ? ' — click below to fetch the next page.' : ' — end of feed.'}
        </p>
      </header>

      <ul className="feed__list">
        {items.map((item) => (
          <li key={item.id} className="feed__item">
            <h2 className="feed__item-title">{item.title}</h2>
            <p className="feed__item-body">{item.body}</p>
            <span className="feed__item-author">— {item.author}</span>
          </li>
        ))}
      </ul>

      <div className="feed__actions">
        <button
          type="button"
          className="feed__load-more"
          onClick={() => fetchNextPage()}
          disabled={!hasNextPage || isFetchingNextPage}
        >
          {isFetchingNextPage
            ? 'Loading…'
            : hasNextPage
              ? 'Load More'
              : 'No more items'}
        </button>

        {isFetching && !isFetchingNextPage ? (
          <span className="feed__refetching">Refreshing…</span>
        ) : null}
      </div>
    </div>
  )
}

